using MiniPharmacie.Data.Database;
using Microsoft.Data.Sqlite;

namespace MiniPharmacie.Business.Services;

public sealed class SupplierInventoryService(DatabaseInitializer db)
{
    public async Task SaveSupplierAsync(long actorId,string name,string? phone,string? email,string? address,long? id=null,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Le nom du fournisseur est obligatoire.");await using var c=db.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,actorId,ct);await using var cmd=c.CreateCommand();cmd.CommandText=id is null?"INSERT INTO Suppliers(Name,Phone,Email,Address) VALUES($n,$p,$e,$a)":"UPDATE Suppliers SET Name=$n,Phone=$p,Email=$e,Address=$a WHERE Id=$id";cmd.Parameters.AddWithValue("$n",name.Trim());cmd.Parameters.AddWithValue("$p",(object?)phone??DBNull.Value);cmd.Parameters.AddWithValue("$e",(object?)email??DBNull.Value);cmd.Parameters.AddWithValue("$a",(object?)address??DBNull.Value);if(id is not null)cmd.Parameters.AddWithValue("$id",id.Value);try{await cmd.ExecuteNonQueryAsync(ct);}catch(SqliteException ex) when(ex.SqliteErrorCode==19){throw new InvalidOperationException("Un fournisseur portant ce nom existe déjà.",ex);}}
    public async Task ArchiveSupplierAsync(long id,long actorId,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,actorId,ct);await using var cmd=c.CreateCommand();cmd.CommandText="UPDATE Suppliers SET IsActive=0 WHERE Id=$id";cmd.Parameters.AddWithValue("$id",id);await cmd.ExecuteNonQueryAsync(ct);}
    public async Task<IReadOnlyList<(long Id,string Name)>> SearchSuppliersAsync(string? search=null,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT Id,Name FROM Suppliers WHERE IsActive=1 AND ($q IS NULL OR Name LIKE $q) ORDER BY Name";cmd.Parameters.AddWithValue("$q",search is null?DBNull.Value:$"%{search}%");var result=new List<(long,string)>();await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))result.Add((r.GetInt64(0),r.GetString(1)));return result;}
    public async Task<long> StartInventoryAsync(long userId,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await AssertManager(c,userId,ct);await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Inventories(UserId,StartedAt,Status) VALUES($u,$d,'EN_COURS');SELECT last_insert_rowid()";cmd.Parameters.AddWithValue("$u",userId);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));var inventory=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));cmd.CommandText="INSERT INTO InventoryLines(InventoryId,ProductId,LotId,ExpectedQuantity) SELECT $i,ProductId,Id,QuantityOnHand FROM Lots";cmd.Parameters.AddWithValue("$i",inventory);await cmd.ExecuteNonQueryAsync(ct);return inventory;}
    public async Task CountInventoryLotAsync(long inventoryId,long lotId,int counted,CancellationToken ct=default){if(counted<0)throw new ArgumentOutOfRangeException(nameof(counted));await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="UPDATE InventoryLines SET CountedQuantity=$q WHERE InventoryId=$i AND LotId=$l AND EXISTS(SELECT 1 FROM Inventories WHERE Id=$i AND Status='EN_COURS')";cmd.Parameters.AddWithValue("$q",counted);cmd.Parameters.AddWithValue("$i",inventoryId);cmd.Parameters.AddWithValue("$l",lotId);if(await cmd.ExecuteNonQueryAsync(ct)==0)throw new InvalidOperationException("Inventaire ou lot introuvable, ou inventaire clôturé.");}
    public async Task ConfirmInventoryAsync(long inventoryId,long userId,string reason,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Un motif est requis pour valider les écarts.");await using var c=db.CreateConnection();await c.OpenAsync(ct);await AssertManager(c,userId,ct);await using var tx=await c.BeginTransactionAsync(ct);await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;cmd.CommandText="SELECT COUNT(*) FROM InventoryLines WHERE InventoryId=$i AND CountedQuantity IS NULL";cmd.Parameters.AddWithValue("$i",inventoryId);if(Convert.ToInt64(await cmd.ExecuteScalarAsync(ct))>0)throw new InvalidOperationException("Toutes les quantités doivent être comptées.");cmd.Parameters.Clear();cmd.CommandText="SELECT ProductId,LotId,ExpectedQuantity,CountedQuantity FROM InventoryLines WHERE InventoryId=$i AND CountedQuantity<>ExpectedQuantity";cmd.Parameters.AddWithValue("$i",inventoryId);var diffs=new List<(long p,long l,int q)>();await using(var r=await cmd.ExecuteReaderAsync(ct)){while(await r.ReadAsync(ct))diffs.Add((r.GetInt64(0),r.GetInt64(1),r.GetInt32(3)));}foreach(var d in diffs){cmd.Parameters.Clear();cmd.CommandText="UPDATE Lots SET QuantityOnHand=$q WHERE Id=$l;INSERT INTO StockAdjustments(ProductId,LotId,UserId,QuantityDelta,Reason,OccurredAt,InventoryId) VALUES($p,$l,$u,$delta,$reason,$date,$i);INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt,Reference,Notes) VALUES($p,$l,$u,'AJUSTEMENT',$delta,$date,$i,$reason)";cmd.Parameters.AddWithValue("$q",d.q);cmd.Parameters.AddWithValue("$l",d.l);cmd.Parameters.AddWithValue("$p",d.p);cmd.Parameters.AddWithValue("$u",userId);cmd.Parameters.AddWithValue("$delta",d.q);cmd.Parameters.AddWithValue("$reason",reason);cmd.Parameters.AddWithValue("$date",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$i",inventoryId);await cmd.ExecuteNonQueryAsync(ct);}cmd.Parameters.Clear();cmd.CommandText="UPDATE Inventories SET Status='TERMINE',CompletedAt=$d WHERE Id=$i AND Status='EN_COURS'";cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$i",inventoryId);if(await cmd.ExecuteNonQueryAsync(ct)!=1)throw new InvalidOperationException("Inventaire introuvable ou déjà clos.");await tx.CommitAsync(ct);}
    private static async Task AssertManager(SqliteConnection c,long user,CancellationToken ct){await using var cmd=c.CreateCommand();cmd.CommandText="SELECT r.Name FROM Users u JOIN Roles r ON r.Id=u.RoleId WHERE u.Id=$u AND u.IsActive=1";cmd.Parameters.AddWithValue("$u",user);var role=(string?)await cmd.ExecuteScalarAsync(ct);if(!string.Equals(role,"Responsable",StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Cette opération est réservée au responsable.");}
}
